// Uses the race clock, which the physics freezes during pause; never receives an alias.
export function createRaceAnalytics(emit){let current=null,started=false,ended=false,reported=0,lastLap=0,best=null;const params=()=>({section:'simulador',circuit:current.circuit,level:current.difficulty});function end(state){if(!started||ended)return;emit('simulator_session_end',{...params(),state,active_ms:Math.max(1,Math.round(Math.max(0,current.elapsed-reported)*1000))});ended=true;}return{end,tick(race){if(current!==race){if(current)end('reset');current=race;started=false;ended=false;reported=race.elapsed;lastLap=race.completedLaps;best=race.bestLap;}if(race.phase==='running'&&!started){started=true;emit('simulator_start',{...params(),state:'started'});}if(!started||ended)return;while(race.completedLaps>lastLap){const index=lastLap++,seconds=race.lapTimes[index];if(!Number.isFinite(seconds))continue;const p={...params(),lap:index+1,lap_ms:Math.round(seconds*1000)};emit('simulator_lap_complete',p);if(best===null||seconds<best){best=seconds;emit('simulator_best_lap',p);}}if(race.elapsed-reported>=30){emit('simulator_engagement',{...params(),active_ms:Math.round((race.elapsed-reported)*1000)});reported=race.elapsed;}if(race.phase==='finished')end('finished');}};}
